from symbols import symbols


def test_plain_def():
    assert symbols("def greet():\n    pass\n") == [("def", "greet", 1)]


def test_async_def():
    assert symbols("async def fetch():\n    pass\n") == [("def", "fetch", 1)]


def test_class():
    assert symbols("class Service:\n    pass\n") == [("class", "Service", 1)]


def test_commented_out_def_is_ignored():
    assert symbols("# def hidden():\n\ndef visible():\n    pass\n") == [
        ("def", "visible", 3),
    ]
